-- Migration: 0011_band_b
-- Imports Band B (B1/B2) vocabulary from OTAB19.xlsx's 'BAN B' sheet — previously
-- dictionary_words only had Band A (A1/A2). order_index preserves the source
-- spreadsheet's original pinyin-alphabetical ordering. example_* columns are left
-- NULL here; filled in by a follow-up migration once examples are authored.
-- A handful of source rows had hanzi/pinyin but no Vietnamese meaning, or pinyin
-- missing entirely, or (one row) hanzi missing entirely — those were hand-filled
-- from general Chinese vocabulary knowledge rather than dropped; see
-- scripts/parse-band-b.js / scripts/output/band-b.review.txt for the raw list this
-- was reconciled against (14 bare alphabet section-header rows and 1 emoji-corrupted
-- row were dropped as unrecoverable, plus 8 exact source duplicates).

